  var DATA_STORE='axm.ai-team.data-runs.v1',dataState=loadDataState();
  function uid(prefix){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);}
  function loadDataState(){try{var d=JSON.parse(localStorage.getItem(DATA_STORE)||'null');if(d&&d.schema==='axm.ai-team.data-runs/v1')return{schema:d.schema,datasets:Array.isArray(d.datasets)?d.datasets:[],runs:Array.isArray(d.runs)?d.runs:[],activeDatasetId:d.activeDatasetId||null};}catch(e){}return{schema:'axm.ai-team.data-runs/v1',datasets:[],runs:[],activeDatasetId:null};}
