  function activeDataset(){return dataState.datasets.find(function(d){return d.id===dataState.activeDatasetId;})||dataState.datasets[0]||null;}
  function renderDataWorkspace(){var ds=activeDataset();if(ds&&!dataState.activeDatasetId)dataState.activeDatasetId=ds.id;var options=dataState.datasets.map(function(d){return'<option value="'+esc(d.id)+'" '+(ds&&d.id===ds.id?'selected':'')+'>'+esc(d.name)+'</option>';}).join('');$('datasetSelect').innerHTML=options||'<option value="">Create a dataset first</option>';$('runDataset').innerHTML=options||'<option value="">No dataset</option>';$('datasetTotal').textContent=dataState.datasets.length;$('exampleTotal').textContent=dataState.datasets.reduce(function(n,d){return n+(d.examples||[]).length;},0);$('runTotal').textContent=dataState.runs.length;
    var examples=ds&&Array.isArray(ds.examples)?ds.examples:[];$('exampleList').innerHTML=examples.length?examples.slice().reverse().map(function(x){return'<article class="record"><header><div><b>'+esc((x.output||'Unlabelled').slice(0,90))+'</b><small>'+esc((x.tags||[]).join(' · ')||'no tags')+'</small></div><span class="record-state '+(x.reviewed?'reviewed':'')+'">'+(x.reviewed?'REVIEWED':'NEEDS REVIEW')+'</span></header><p>'+esc(x.input||'')+'</p><div class="record-actions"><button data-review-example="'+esc(x.id)+'">'+(x.reviewed?'Reopen review':'Mark reviewed')+'</button><button class="danger" data-delete-example="'+esc(x.id)+'">Delete</button></div></article>';}).join(''):'<div class="empty">'+(ds?'No examples in this dataset yet.':'Create a dataset to begin.')+'</div>';
    $('runList').innerHTML=dataState.runs.length?dataState.runs.slice().reverse().map(function(r){var d=dataState.datasets.find(function(x){return x.id===r.datasetId;});return'<article class="record"><header><div><b>'+esc(r.name)+'</b><small>'+esc((d?d.name:'missing dataset')+' · '+(r.model||'model not recorded'))+'</small></div><span class="record-state '+(r.accepted?'accepted':'')+'">'+esc(r.accepted?'ACCEPTED':r.status)+'</span></header><p>'+esc(r.evidence||'No evidence note recorded.')+'</p><div class="record-actions">'+(r.status==='PLANNED'?'<button data-run-state="'+esc(r.id)+'" data-next="RUNNING">Start</button>':'')+(r.status==='RUNNING'?'<button data-run-state="'+esc(r.id)+'" data-next="COMPLETED">Complete</button><button data-run-state="'+esc(r.id)+'" data-next="FAILED">Fail</button>':'')+((r.status==='COMPLETED'||r.status==='FAILED')?'<button data-accept-run="'+esc(r.id)+'">'+(r.accepted?'Reopen review':'Accept evidence')+'</button>':'')+'<button class="danger" data-delete-run="'+esc(r.id)+'">Delete</button></div></article>';}).join(''):'<div class="empty">No training runs recorded.</div>';
    $('exampleList').querySelectorAll('[data-review-example]').forEach(function(b){b.onclick=function(){var x=examples.find(function(e){return e.id===b.dataset.reviewExample;});if(x){x.reviewed=!x.reviewed;x.reviewedAt=x.reviewed?new Date().toISOString():null;saveData(x.reviewed?'Example reviewed':'Example returned to review');}};});$('exampleList').querySelectorAll('[data-delete-example]').forEach(function(b){b.onclick=function(){if(!confirm('Delete this labelled example?'))return;ds.examples=examples.filter(function(e){return e.id!==b.dataset.deleteExample;});saveData('Example deleted');};});$('runList').querySelectorAll('[data-run-state]').forEach(function(b){b.onclick=function(){var r=dataState.runs.find(function(x){return x.id===b.dataset.runState;});if(r){r.status=b.dataset.next;r.updatedAt=new Date().toISOString();r.accepted=false;saveData('Run marked '+r.status);}};});$('runList').querySelectorAll('[data-accept-run]').forEach(function(b){b.onclick=function(){var r=dataState.runs.find(function(x){return x.id===b.dataset.acceptRun;});if(r){r.accepted=!r.accepted;r.acceptedAt=r.accepted?new Date().toISOString():null;saveData(r.accepted?'Run evidence accepted by human':'Run returned to review');}};});$('runList').querySelectorAll('[data-delete-run]').forEach(function(b){b.onclick=function(){if(!confirm('Delete this training-run record?'))return;dataState.runs=dataState.runs.filter(function(r){return r.id!==b.dataset.deleteRun;});saveData('Run record deleted');};});}
  function createDataset(){var name=$('datasetName').value.trim(),purpose=$('datasetPurpose').value.trim();if(!name)return toast('Dataset name required');var d={id:uid('dataset'),name:name.slice(0,80),purpose:purpose.slice(0,180),createdAt:new Date().toISOString(),examples:[]};dataState.datasets.push(d);dataState.activeDatasetId=d.id;$('datasetName').value='';$('datasetPurpose').value='';saveData('Dataset created');}
