  function childFrame(source){return[].slice.call(document.querySelectorAll('.team-frame,.service-frame')).find(function(f){return f.contentWindow===source;});}
  function routePromptComparison(message,source){if(source!==frames.prompts.contentWindow||!message||message.schema!=='axm.ai-team-prompt/v1'||message.type!=='axm-ai-team-prompt')return false;var p=message.prompt||{},text=String(p.text||'').slice(0,16000);if(!text){toast('Prompt handoff refused · empty prompt');return true;}pendingPrompt={id:String(p.id||''),title:String(p.title||'Prompt comparison').slice(0,120),revision:Math.max(1,Number(p.revision)||1),text:text,role:String(p.role||'any-model').slice(0,80),provider:String(p.provider||'').slice(0,120),tags:Array.isArray(p.tags)?p.tags.slice(0,20).map(String):[]};selectView('models');if(frames.models.dataset.ready){frames.models.contentWindow.postMessage({schema:'axm.ai-team-prompt/v1',type:'axm-model-compare-prompt',prompt:pendingPrompt},'*');pendingPrompt=null;}toast('Prompt revision routed to Model Evaluation');return true;}
